<?php declare(strict_types=1);use yii\helpers\Html;FMonitor2\YiiRuntime\Assets\AuthAssetBundle::register($this);$title=$stage==='initial'?'Задайте первый пароль':($stage==='password'?'Введите пароль':'Вход в FMonitor');$this->beginPage();?><!doctype html><html lang="ru"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=Html::encode($title)?> — FMonitor</title><link rel="icon" href="/pilot/assets/favicon.svg"><?php $this->head()?></head><body class="shlz-scope fm2-auth-page"><?php $this->beginBody()?><a class="fm2-skip shlz-link" href="#main-content">Перейти к содержанию</a><main class="fm2-auth-layout" id="main-content" tabindex="-1"><section class="fm2-auth-brand" aria-label="FMonitor"><img src="/pilot/assets/favicon.svg" alt="" width="56" height="56"><div><strong>FMonitor</strong><span>Управление монтажными работами</span></div></section><section class="fm2-auth-card"><div class="fm2-auth-heading"><span class="fm2-auth-kicker">ЩЛЗ · защищённый контур</span><h1><?=Html::encode($title)?></h1><p><?=$stage==='email'?'Введите корпоративный email.':($stage==='initial'?'Доступ уже предоставлен. Создайте пароль для первого входа.':'Введите пароль для этого email.')?></p></div><form method="post" action="<?=$stage==='initial'?'/pilot/first-password':Html::encode($path)?>" class="fm2-auth-form"><input type="hidden" name="<?=Html::encode(Yii::$app->request->csrfParam)?>" value="<?=Html::encode(Yii::$app->request->csrfToken)?>"><?php if($stage!=='email'):?><input type="hidden" name="email" value="<?=Html::encode($email)?>"><p class="fm2-auth-identity"><strong><?=Html::encode($email)?></strong></p><label class="shlz-field"><span class="shlz-field__label"><?=$stage==='initial'?'Новый пароль':'Пароль'?></span><span class="shlz-field__control"><input class="shlz-input" type="password" name="password"<?=$stage==='initial'?' aria-describedby="password-requirements"':''?> autocomplete="<?=$stage==='initial'?'new-password':'current-password'?>" minlength="10" maxlength="200" required autofocus></span></label><?php if($stage==='initial'):?><label class="shlz-field"><span class="shlz-field__label">Повторите пароль</span><span class="shlz-field__control"><input class="shlz-input" type="password" name="passwordConfirmation" aria-describedby="password-requirements" autocomplete="new-password" minlength="10" maxlength="200" required></span></label><p class="fm2-auth-help" id="password-requirements">10–200 символов: строчную и заглавную латинские буквы, цифру и спецсимвол.</p><?php endif?><?php else:?><label class="shlz-field"><span class="shlz-field__label">Корпоративный email</span><span class="shlz-field__control"><input class="shlz-input" type="email" name="email" value="<?=Html::encode($email)?>" placeholder="name@shlz.ru" autocomplete="username" required autofocus></span></label><?php endif?><?php if($error!==''):?><p class="fm2-auth-error" role="alert"><?=Html::encode($error)?></p><?php endif?><button class="shlz-button shlz-button--primary fm2-auth-submit" type="submit"><?=$stage==='email'?'Продолжить':($stage==='initial'?'Сохранить пароль':'Войти')?></button><?php if($stage==='password'):?><a class="fm2-auth-back" href="/pilot/forgot-password">Забыли пароль?</a><?php endif?><?php if($stage!=='email'):?><a class="fm2-auth-back" href="<?=Html::encode($path)?>">Войти с другим email</a><?php endif?></form></section></main><?php $this->endBody()?></body></html><?php $this->endPage()?>
